static a64_compact_raw_fallback_result_t compact_raw_fallback(
        void *opaque, a64_compact_raw_code_window_t *next_window) {
    compact_raw_fallback_context_t *context =
        (compact_raw_fallback_context_t *)opaque;
    arm_cpu_t *cpu;
    uint32_t step_block;
    uint32_t next_block;
    uint32_t insn;
    unsigned width;
    unsigned offset;
    bool thumb;
    bool priv;
    bool crossed;
    unsigned result;

    if (!context || !context->machine || !context->state || !next_window)
        return A64_COMPACT_RAW_FALLBACK_NO_RETIRE;
    cpu = &context->machine->cpu;
    step_block = cpu->r[15] & ~UINT32_C(0x3ff);
    thumb = (cpu->cpsr & ARM_CPSR_T) != 0u;
    priv = (cpu->cpsr & ARM_CPSR_MODE_MASK) != ARM_MODE_USR;
    width = thumb ? 2u : 4u;

    /* A window exit does not itself require an architectural step. User mode
     * can reuse an exact FETCH witness immediately. A privileged prefix first
     * delegates every retirement since the previous continuation to the
     * machine-owned device/clock boundary; only if that gate still admits
     * execution may it prove and publish the next window. The native runner
     * commits its one-cycle-per-retirement counter before this callback, so the
     * cycle delta is the exact prefix length and cannot include an interpreter
     * fallback. Unsupported instructions still stop here: arm_step() remains
     * outside the privileged resident interval and remains the sole owner of
     * walks, faults, MMIO and control-state changes. */
    if (context->state->compact_raw_window_refill_enabled &&
        (!priv ||
         context->state->compact_raw_privileged_window_refill_enabled) &&
        step_block != context->fetch_block &&
        (cpu->r[15] & (width - 1u)) == 0u) {
        unsigned boundary_delta = 0u;
        if (priv) {
            uint64_t retired64;
            if (!context->retirement_boundary)
                return A64_COMPACT_RAW_FALLBACK_NO_RETIRE;
            retired64 = cpu->cycles - context->boundary_cycles;
            if (!retired64 || retired64 > UINT_MAX ||
                retired64 > context->budget - context->boundary_retired)
                return A64_COMPACT_RAW_FALLBACK_NO_RETIRE;
            boundary_delta = (unsigned)retired64;
            bool may_continue = context->retirement_boundary(
                context->retirement_opaque, boundary_delta);
            context->boundary_retired += boundary_delta;
            context->boundary_cycles = cpu->cycles;
            context->state->compact_raw_privileged_boundary_retired +=
                boundary_delta;
            if (!may_continue)
                return A64_COMPACT_RAW_FALLBACK_NO_RETIRE;

            /* The boundary may have sampled a host input, raised an interrupt
             * or invalidated a translation. Re-read every CPU-side admission
             * fact before consuming a pointer. Device refresh cannot change
             * PC or mode, but keeping those checks explicit makes the contract
             * fail closed if that invariant ever changes. */
            thumb = (cpu->cpsr & ARM_CPSR_T) != 0u;
            priv = (cpu->cpsr & ARM_CPSR_MODE_MASK) != ARM_MODE_USR;
            width = thumb ? 2u : 4u;
            step_block = cpu->r[15] & ~UINT32_C(0x3ff);
            if (!priv || !arm_mode_is_valid(cpu->cpsr) ||
                (cpu->cpsr & ARM_CPSR_E) != 0u || cpu->abort_pending ||
                (cpu->fiq_line && !(cpu->cpsr & ARM_CPSR_F)) ||
                (cpu->irq_line && !(cpu->cpsr & ARM_CPSR_I)) ||
                step_block == context->fetch_block ||
                (cpu->r[15] & (width - 1u)) != 0u)
                return A64_COMPACT_RAW_FALLBACK_NO_RETIRE;
        }
        if (!arm_fetch_cache_try_refill(cpu, cpu->r[15], priv))
            return A64_COMPACT_RAW_FALLBACK_NO_RETIRE;
        offset = cpu->r[15] - step_block;
        insn = (uint32_t)cpu->fetch_host[offset] |
               ((uint32_t)cpu->fetch_host[offset + 1u] << 8);
        if (!thumb) {
            insn |= (uint32_t)cpu->fetch_host[offset + 2u] << 16;
            insn |= (uint32_t)cpu->fetch_host[offset + 3u] << 24;
        }
        if ((unsigned)a64_compact_raw_classify_instruction(cpu, insn, thumb) <
            (unsigned)A64_COMPACT_RAW_ADMITTED_COUNT) {
            next_window->code = cpu->fetch_host;
            next_window->code_base = step_block;
            next_window->code_bytes = UINT32_C(0x400);
            context->state->compact_raw_window_crossings++;
            context->state->compact_raw_window_reloads++;
            context->state->compact_raw_window_fast_refills++;
            if (priv) {
                context->state->compact_raw_privileged_window_refills++;
            }
            context->fetch_block = step_block;
            return A64_COMPACT_RAW_FALLBACK_NO_RETIRE_CONTINUE;
        }
    }

    result = s5l8900_static_a64_fallback_step(context->machine,
                                              &context->status);
    if (result > A64_COMPACT_RAW_FALLBACK_RETIRE_STOP)
        return A64_COMPACT_RAW_FALLBACK_NO_RETIRE;
    if (result != A64_COMPACT_RAW_FALLBACK_RETIRE_CONTINUE)
        return (a64_compact_raw_fallback_result_t)result;

    next_block = cpu->r[15] & ~UINT32_C(0x3ff);
    crossed = step_block != context->fetch_block ||
              next_block != context->fetch_block;
    if (crossed) context->state->compact_raw_window_crossings++;
    /* This refill consumes only an interpreter-owned live TLB/host-RAM
     * witness. It cannot walk the MMU or enter a fault/device path inside the
     * resident interval; refusal returns to the outer machine loop. */
    priv = (cpu->cpsr & ARM_CPSR_MODE_MASK) != ARM_MODE_USR;
    if ((cpu->r[15] & ((cpu->cpsr & ARM_CPSR_T) ? 1u : 3u)) != 0u ||
        !arm_fetch_cache_try_refill(cpu, cpu->r[15], priv)) {
        if (crossed) context->state->compact_raw_window_stops++;
        return A64_COMPACT_RAW_FALLBACK_RETIRE_STOP;
    }

    next_window->code = cpu->fetch_host;
    next_window->code_base = next_block;
    next_window->code_bytes = UINT32_C(0x400);
    if (next_block != context->fetch_block) {
        context->state->compact_raw_window_reloads++;
        context->fetch_block = next_block;
    }
    return A64_COMPACT_RAW_FALLBACK_RETIRE_CONTINUE;
}

static unsigned try_compact_raw(
        s5l8900_t *m, static_a64_state_t *state, unsigned budget,
        arm_status_t *status, bool *known_negative,
        s5l8900_static_a64_retirement_boundary_fn retirement_boundary,
        void *retirement_opaque, unsigned *boundary_retired) {
    arm_cpu_t *cpu = &m->cpu;
    compact_raw_fallback_context_t fallback_context = {
        .machine = m,
        .state = state,
        .status = ARM_OK,
        .fetch_block = 0u,
        .boundary_cycles = m->cpu.cycles,
        .budget = budget,
        .boundary_retired = 0u,
        .retirement_boundary = retirement_boundary,
        .retirement_opaque = retirement_opaque,
    };
    uint32_t fetch_block;
    uint32_t pc;
    unsigned width;
    bool thumb;
    bool priv;
    unsigned completed = 0u;
    unsigned native_completed = 0u;
    unsigned fallback_completed = 0u;
    uint64_t window_cache_hits = 0u;

    if (known_negative) *known_negative = false;
    if (boundary_retired) *boundary_retired = 0u;
    memset(&state->compact_pending, 0, sizeof state->compact_pending);
    state->compact_raw_attempts++;
    /* A branch can reach any address in the live 1 KiB window, so a sparse
     * pre-step target list is not enough: any installed host hook disables
     * this path until a target-aware in-loop guard exists. */
    if (!budget || m->pre_step_hook ||
        cpu->arch != ARM_ARCH_V6_ARM1176 ||
        !arm_mode_is_valid(cpu->cpsr) || cpu->abort_pending ||
        (cpu->cpsr & ARM_CPSR_E) != 0u ||
        (cpu->fiq_line && !(cpu->cpsr & ARM_CPSR_F)) ||
        (cpu->irq_line && !(cpu->cpsr & ARM_CPSR_I))) {
        state->compact_raw_refusals.guard++;
        return 0u;
    }
    priv = (cpu->cpsr & ARM_CPSR_MODE_MASK) != ARM_MODE_USR;
    if (priv) {
        state->compact_raw_privileged_attempts++;
        if (!state->compact_raw_privileged_enabled) {
            state->compact_raw_refusals.privileged++;
            return 0u;
        }
    }

    pc = cpu->r[15];
    thumb = (cpu->cpsr & ARM_CPSR_T) != 0u;
    width = thumb ? 2u : 4u;
    /* The native loop selects A32/Thumb width from CPSR on every iteration.
     * Requiring A32 alignment here discarded every valid Thumb entry at
     * address 2 modulo 4 before that loop could inspect it. */
    if ((pc & (width - 1u)) != 0u) {
        state->compact_raw_refusals.alignment++;
        return 0u;
    }
    fetch_block = pc & ~UINT32_C(0x3ff);
    if (!cpu->fetch_host || cpu->fetch_blk != fetch_block ||
        cpu->fetch_gen != cpu->tlb_gen || cpu->fetch_priv != priv) {
        state->compact_raw_refusals.fetch_witness++;
        return 0u;
    }
    fallback_context.fetch_block = fetch_block;
    if (!a64_compact_raw_run_code_window_resident_cached(
            cpu, cpu->fetch_host, fetch_block, UINT32_C(0x400), budget,
            compact_raw_fallback, &fallback_context,
            state->compact_raw_window_cache_enabled, &window_cache_hits,
            &completed,
            &native_completed, &fallback_completed)) {
        state->compact_raw_refusals.runner++;
        return 0u;
    }
    if (status) *status = fallback_context.status;
    if (boundary_retired)
        *boundary_retired = fallback_context.boundary_retired;
    state->compact_raw_window_cache_hits += window_cache_hits;
    state->compact_raw_window_crossings += window_cache_hits;
    state->compact_raw_window_reloads += window_cache_hits;
    if (completed) {
        state->compact_raw_calls++;
        state->compact_raw_retired += native_completed;
        state->compact_raw_fallback_retired += fallback_completed;
        if (priv) {
            state->compact_raw_privileged_calls++;
            state->compact_raw_privileged_retired += native_completed;
        }
        state->retired += native_completed;
    } else {
        state->compact_raw_refusals.zero_retired++;
    }
    /* A positive privileged prefix followed by a zero-retirement callback is
     * the exact redundant-entry shape observed on the phone.  Preserve the
     * untouched instruction only until the post-prefix device tick; the
     * machine loop revalidates and consumes it before one literal arm_step().
     * A completed budget did not inspect the next instruction, and a retired
     * fallback is already accounted, so neither may arm the bypass. */
    if (completed && completed < budget && fallback_completed == 0u &&
        fallback_context.status == ARM_OK &&
        compact_pending_capture(m, state) && known_negative)
        *known_negative = true;
    return completed;
}

static unsigned try_persistent(s5l8900_t *m, static_a64_state_t *state,
                               unsigned budget) {
    arm_cpu_t *cpu = &m->cpu;
    static_a64_chain_context_t context = {
        .state = state,
        .machine = m,
        .fetch_block = cpu->r[15] & ~UINT32_C(0x3ff)
    };
    const a64_static_block_t *first =
        select_persistent_block(&context, cpu->r[15], budget);
    unsigned completed = 0u;
    unsigned blocks = 0u;

    if (!first) return 0u;
    if (!a64_static_run_memory_hits_chain(cpu, first, m->ram, m->ram_size,
                                          budget, persistent_next, &context,
                                          state->vfp_fp_session_enabled,
                                          &completed, &blocks)) {
        /* A pre-execution contract mismatch must not become a sticky cache
         * hit. Runtime read/VFP misses are successful exact-prefix returns. */
        if (context.last_entry)
            invalidate_entry(state, context.last_entry);
        return 0u;
    }
    state->retired += completed;
    if (blocks > 1u) {
        state->chained_blocks += blocks - 1u;
        state->persistent_chained_blocks += blocks - 1u;
    }
    return completed;
}

static unsigned try_graph(s5l8900_t *m, static_a64_state_t *state,
                          unsigned budget) {
    arm_cpu_t *cpu = &m->cpu;
    static_a64_chain_context_t context = {
        .state = state,
        .machine = m,
        .fetch_block = cpu->r[15] & ~UINT32_C(0x3ff)
    };
    const a64_static_block_t *first =
        select_persistent_block(&context, cpu->r[15], budget);
    unsigned completed = 0u;
    unsigned blocks = 0u;

    if (!first) return 0u;
    /* The direct table is intentionally scoped by offset, so a descriptor at
     * the same offset in another 1 KiB fetch block may have replaced this
     * cache entry's node. Ensure the C-validated first head is published, but
     * leave an already-owned valid node untouched on the common hot hit. This
     * lets a returning block recover without recopying 128 bytes per entry. */
    {
        static_a64_entry_t *entry = context.last_entry;
        a64_static_graph_node_t *node =
            &state->graph_nodes[graph_index(entry->pc, entry->thumb)];
        if (node->owner != entry || !node->valid || !node->supported)
            publish_graph_node(state, entry);
    }
    if (!a64_static_run_memory_hits_graph(cpu, first, m->ram, m->ram_size,
                                          budget, state->graph_nodes,
                                          state->vfp_fp_session_enabled,
                                          &completed, &blocks)) {
        if (context.last_entry)
            invalidate_entry(state, context.last_entry);
        return 0u;
    }
    state->retired += completed;
    if (blocks > 1u) {
        state->chained_blocks += blocks - 1u;
        state->graph_chained_blocks += blocks - 1u;
    }
    return completed;
}
#endif

unsigned s5l8900_static_a64_try(s5l8900_t *m, unsigned max_insns,
                                bool *known_negative,
                                arm_status_t *status,
                                s5l8900_static_a64_retirement_boundary_fn
                                    retirement_boundary,
                                void *retirement_opaque,
                                unsigned *boundary_retired) {
#if defined(S5LBOX_STATIC_A64_ENGINE)
    static_a64_state_t *state = static_state(m);
    arm_cpu_t *cpu;
    unsigned budget;
    unsigned retired = 0u;
    unsigned executed_blocks = 0u;
    uint32_t refill_pc = 0u;
    uint32_t refill_gen = 0u;
    bool refill_thumb = false;
    bool refill_priv = false;
    bool refilled = false;

    if (known_negative) *known_negative = false;
    if (status) *status = ARM_OK;
    if (boundary_retired) *boundary_retired = 0u;
    if (!state || !state->enabled || !max_insns ||
        !a64_static_host_available() || !m->ram || !m->ram_size ||
        (m->ram_size & (m->ram_size - 1u)) != 0u)
        return 0u;

    cpu = &m->cpu;
    if (state->fetch_refill_enabled &&
        cpu->arch == ARM_ARCH_V6_ARM1176 &&
        arm_mode_is_valid(cpu->cpsr) && !cpu->abort_pending &&
        !(cpu->fiq_line && !(cpu->cpsr & ARM_CPSR_F)) &&
        !(cpu->irq_line && !(cpu->cpsr & ARM_CPSR_I))) {
        const uint32_t pc = cpu->r[15];
        const bool thumb = (cpu->cpsr & ARM_CPSR_T) != 0u;
        const bool priv =
            (cpu->cpsr & ARM_CPSR_MODE_MASK) != ARM_MODE_USR;
        const uint32_t fetch_block = pc & ~UINT32_C(0x3ff);
        const unsigned width = thumb ? 2u : 4u;
        if ((pc & (width - 1u)) == 0u &&
            (!cpu->fetch_host || cpu->fetch_blk != fetch_block ||
             cpu->fetch_gen != cpu->tlb_gen || cpu->fetch_priv != priv)) {
            if (!refill_predictor_allows(state, pc, cpu->tlb_gen, thumb,
                                         priv))
                return 0u;
            state->fetch_refill_attempts++;
            if (!arm_fetch_cache_try_refill(cpu, pc, priv)) return 0u;
            state->fetch_refill_hits++;
            refill_pc = pc;
            refill_gen = cpu->tlb_gen;
            refill_thumb = thumb;
            refill_priv = priv;
            refilled = true;
        }
    }
    budget = max_insns < state->chain_limit
           ? max_insns : state->chain_limit;
    if (state->compact_raw_enabled) {
        bool compact_known_negative = false;
        unsigned completed = try_compact_raw(
            m, state, budget, status, &compact_known_negative,
            retirement_boundary, retirement_opaque, boundary_retired);
        if (refilled)
            refill_predictor_record(state, refill_pc, refill_gen,
                                    refill_thumb, refill_priv, completed,
                                    budget);
        if (known_negative) *known_negative = compact_known_negative;
        return completed;
    }
    if (state->graph_enabled) {
        unsigned completed = try_graph(m, state, budget);
        if (refilled)
            refill_predictor_record(state, refill_pc, refill_gen,
                                    refill_thumb, refill_priv, completed,
                                    budget);
        if (known_negative && completed && completed < budget &&
            current_cached_unsupported(m, state))
            *known_negative = true;
        return completed;
    }
    if (state->persistent) {
        unsigned completed = try_persistent(m, state, budget);
        if (refilled)
            refill_predictor_record(state, refill_pc, refill_gen,
                                    refill_thumb, refill_priv, completed,
                                    budget);
        if (known_negative && completed && completed < budget &&
            current_cached_unsupported(m, state))
            *known_negative = true;
        return completed;
    }

    while (retired < budget) {
        uint32_t pc;
        uint32_t fetch_block;
        unsigned width;
        unsigned offset;
        unsigned candidate_insns;
        unsigned raw_len;
        unsigned remaining = budget - retired;
        unsigned completed = 0u;
        bool thumb;
        bool priv;
        const uint8_t *bytes;
        static_a64_entry_t *entry;
        a64_static_block_t bounded_block;
        const a64_static_block_t *run_block;

        /* Recheck every head. Signed instructions cannot change the MMU,
         * privilege, interrupt masks or instruction state, but keeping these
         * gates local makes that invariant fail closed if the subset grows. */
        if (cpu->arch != ARM_ARCH_V6_ARM1176 ||
            !arm_mode_is_valid(cpu->cpsr) || cpu->abort_pending ||
            (cpu->fiq_line && !(cpu->cpsr & ARM_CPSR_F)) ||
            (cpu->irq_line && !(cpu->cpsr & ARM_CPSR_I)))
            break;

        pc = cpu->r[15];
        thumb = (cpu->cpsr & ARM_CPSR_T) != 0u;
        priv = (cpu->cpsr & ARM_CPSR_MODE_MASK) != ARM_MODE_USR;
        width = thumb ? 2u : 4u;
        if ((pc & (width - 1u)) != 0u) break;
        if (s5l8900_pre_step_target(m, pc)) break;

        fetch_block = pc & ~UINT32_C(0x3ff);
        /* A cross-block target must return to arm_step(), which alone owns
         * instruction translation, MMU faults and the new fetch witness. */
        if (!cpu->fetch_host || cpu->fetch_blk != fetch_block ||
            cpu->fetch_gen != cpu->tlb_gen || cpu->fetch_priv != priv)
            break;

        offset = pc - fetch_block;
        candidate_insns = (0x400u - offset) / width;
        if (candidate_insns > A64_STATIC_MAX_INSNS)
            candidate_insns = A64_STATIC_MAX_INSNS;
        candidate_insns = cap_before_pre_step_target(
            m, pc, width, candidate_insns);
        if (!candidate_insns) break;
        raw_len = candidate_insns * width;
        bytes = cpu->fetch_host + offset;

        entry = &state->cache[cache_index(pc, thumb, cpu->fetch_gen)];
        if (!entry_matches(entry, cpu, bytes, pc, thumb, priv, raw_len))
            decode_entry(state, entry, cpu, bytes, pc, thumb, priv,
                         candidate_insns, raw_len);
        if (!entry->supported) break;
        run_block = &entry->block;
        if (run_block->insn_count > remaining) {
            /* The total chain never crosses its caller/time/device budget.
             * Decode an exact bounded prefix without mutating the cache. */
            if (!decode_longest(bytes, remaining, thumb, pc,
                                state->indirect_enabled,
                                state->thumb_conditional_enabled,
                                state->vstr_enabled,
                                state->stm_enabled, state->ldm_enabled,
                                state->vstm_enabled,
                                state->vfp_arithmetic_enabled,
                                &bounded_block))
                break;
            run_block = &bounded_block;
        }

        if (!a64_static_run_memory_hits_decoded(cpu, run_block, m->ram,
                                                m->ram_size,
                                                state->vfp_fp_session_enabled,
                                                &completed)) {
            /* Fail closed, and make a transient contract mismatch re-decode.
             * The decoded runner refuses before changing guest state. */
            invalidate_entry(state, entry);
            break;
        }
        if (!completed) break;
        if (executed_blocks) state->chained_blocks++;
        executed_blocks++;
        retired += completed;
        if (completed != run_block->insn_count) break;
    }

    state->retired += retired;
    if (refilled)
        refill_predictor_record(state, refill_pc, refill_gen, refill_thumb,
                                refill_priv, retired, budget);
    if (known_negative && retired && retired < budget &&
        current_cached_unsupported(m, state))
        *known_negative = true;
    return retired;
#else
    (void)m;
    (void)max_insns;
    (void)retirement_boundary;
    (void)retirement_opaque;
    if (known_negative) *known_negative = false;
    if (status) *status = ARM_OK;
    if (boundary_retired) *boundary_retired = 0u;
    return 0u;
#endif
}

bool s5l8900_static_a64_commit_known_negative_bypass(s5l8900_t *m) {
#if defined(S5LBOX_STATIC_A64_ENGINE)
    static_a64_state_t *state = static_state(m);
    if (state && state->compact_raw_enabled) {
        bool matches = compact_pending_matches(m, state);
        /* Whether the post-tick witness passed or failed, the pending record
         * applies to this boundary only. Never turn it into a sticky opcode
         * exclusion that could hide a later native opportunity. */
        memset(&state->compact_pending, 0, sizeof state->compact_pending);
        if (!matches) return false;
        state->known_negative_bypasses++;
        return true;
    }
    /* The device tick between detection and this call can invalidate fetch or
     * change RAM. Repeat the complete negative witness before skipping work. */
    if (!current_cached_unsupported(m, state)) return false;
    state->known_negative_bypasses++;
    return true;
#else
    (void)m;
    return false;
#endif
}

void s5l8900_static_a64_dispose(s5l8900_t *m) {
    if (!m) return;
#if defined(S5LBOX_STATIC_A64_ENGINE)
    free(m->static_a64_state);
#endif
    m->static_a64_state = NULL;
}
